async function renderGst(){if(isAu())return renderBas();
  if(!q('finGstFrom').value||!q('finGstTo').value){const r=gstPeriodFor(new Date(),0);q('finGstFrom').value=r.from;q('finGstTo').value=r.to}
  const cfg=gstConfig();
  if(q('finGstDue'))q('finGstDue').textContent=gstDueDate(q('finGstTo').value)||'—';
  if(q('finGstBasis'))q('finGstBasis').textContent=human(cfg.accounting_basis||cfg.gst_accounting_basis||'invoice');
  if(q('finGstFrequency'))q('finGstFrequency').textContent=human(cfg.filing_frequency||cfg.gst_filing_frequency||'two_monthly');
  if(q('finGstStatus'))q('finGstStatus').textContent='Calculating…';
  try{
    const c=await gstCalcServer();
    const warnings=[...gstEligibilityWarning(),...c.reviewItems.map(x=>`${x.severity==='blocking'?'Review required':'Warning'}: ${x.message||x.code}`)];
    if(q('finGstWarning')){q('finGstWarning').hidden=!warnings.length;q('finGstWarning').innerHTML=warnings.map(esc).join('<br>')}
    renderMetric('finGstSalesEx',c.sales);renderMetric('finGstCollected',c.gstCollected);renderMetric('finGstPurchasesEx',c.purchaseEx);renderMetric('finGstPaid',c.gstPaid);if(q('finGstAdjustments'))renderMetric('finGstAdjustments',c.debitAdjustments-c.creditAdjustments);
    q('finGstNetLabel').textContent=c.gstNet>=0?'GST to Pay':'GST Refund';renderMetric('finGstNet',Math.abs(c.gstNet));
    q('finGstSalesRows').innerHTML=c.invoices.length?c.invoices.map(x=>`<tr><td>${esc(x.invoice_date)}</td><td>${esc(x.invoice_number)}</td><td>${esc(x.customer_name||'-')}</td><td>${money(x.total)}</td><td>${money(x.gst)}</td></tr>`).join(''):'<tr><td colspan="5">No sales GST evidence in this period.</td></tr>';
    q('finGstExpenseRows').innerHTML=c.expenses.length?c.expenses.map(x=>`<tr><td>${esc(x.invoice_date)}</td><td>${esc(x.supplier_name||'-')}</td><td>${esc(x.expense_number)}</td><td>${money(x.total_amount)}</td><td>${money(x.gst_amount)}</td></tr>`).join(''):'<tr><td colspan="5">No purchase GST evidence in this period.</td></tr>';
    if(q('finGstAdjustmentRows'))q('finGstAdjustmentRows').innerHTML=c.adjustments.length?c.adjustments.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(human(x.type))}</td><td>${money((x.direction==='credit'?-1:1)*num(x.gst_amount))}</td><td>${esc(x.reason||x.reference||'')}</td></tr>`).join(''):'<tr><td colspan="4">No GST adjustments.</td></tr>';
    if(q('finGstExcludedRows'))q('finGstExcludedRows').innerHTML='<tr><td colspan="5">No excluded / no GST rows are separated by the current GST calculation.</td></tr>';
    const saved=state.gstReturns.find(x=>x.period_start===c.from&&x.period_end===c.to),due=gstDueDate(c.to),overdue=due&&due<today()&&saved?.status!=='finalised';
    q('finGstStatus').textContent=saved?`${human(saved.status)}${overdue?' · Overdue':''}`:(overdue?'Open · Overdue':'Not Saved');
    renderGstFriendly(c,{saved,overdue,warnings});
    q('finGstFinalise').disabled=saved?.status==='finalised'||c.reviewItems.some(x=>x.severity==='blocking');
    q('finGstHistoryRows').innerHTML=state.gstReturns.length?state.gstReturns.map(x=>{const conflict=x.status==='finalised'&&x.period_start<=c.to&&x.period_end>=c.from&&!(x.period_start===c.from&&x.period_end===c.to);return `<tr><td>${esc(x.period_start)} to ${esc(x.period_end)}${conflict?' · <strong>Period conflict</strong>':''}</td><td>${money(x.gst_collected)}</td><td>${money(x.gst_paid)}</td><td>${x.gst_net>=0?money(x.gst_net)+' payable':money(Math.abs(x.gst_net))+' refund'}</td><td><span class="badge">${esc(human(x.status))}${conflict?' · Review':''}</span></td></tr>`}).join(''):'<tr><td colspan="5">No saved GST returns yet.</td></tr>';
  }catch(e){
    console.error('GST calculation/render failed',e);
    state.gstCurrentCalc=null;
    if(q('finGstStatus'))q('finGstStatus').textContent='Calculation failed';
    if(q('finGstWarning')){q('finGstWarning').hidden=false;q('finGstWarning').textContent=`GST calculation failed: ${e.message||e}`}
  }finally{
    if(q('finGstStatus')&&q('finGstStatus').textContent==='Calculating…')q('finGstStatus').textContent='Calculation failed';
  }
}
